package com.srent.security;
import org.springframework.http.HttpMethod;
import com.fasterxml.jackson.databind.ObjectMapper; import com.srent.config.AppProperties; import com.srent.user.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.http.MediaType; import org.springframework.security.authentication.*; import org.springframework.security.authentication.dao.DaoAuthenticationProvider; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.time.Instant; import java.util.*;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor
public class SecurityConfig {
    private final JwtAuthenticationFilter jwtFilter; private final UserRepository users; private final AppProperties props;
    @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
    @Bean AuthenticationManager authManager(PasswordEncoder encoder){var p=new DaoAuthenticationProvider();p.setUserDetailsService(email->UserPrincipal.from(users.findByEmailIgnoreCase(email).orElseThrow()));p.setPasswordEncoder(encoder);return new ProviderManager(p);}
    @Bean SecurityFilterChain chain(HttpSecurity h,ObjectMapper mapper)throws Exception{return h.csrf(c->c.disable()).cors(c->c.configurationSource(cors())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a
        .requestMatchers("/api/v1/auth/**","/actuator/health","/v3/api-docs/**","/swagger-ui/**").permitAll()
        .requestMatchers("/api/v1/admin/**").hasRole("ADMIN").requestMatchers(HttpMethod.GET,"/api/v1/rooms","/api/v1/rooms/*","/api/v1/rooms/*/video","/api/v1/rooms/*/images").permitAll().anyRequest().authenticated())
        .exceptionHandling(e->e.authenticationEntryPoint((req,res,x)->{res.setStatus(401);res.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(res.getOutputStream(),Map.of("code","UNAUTHORIZED","message","Cần đăng nhập","timestamp",Instant.now().toString(),"path",req.getRequestURI()));}).accessDeniedHandler((req,res,x)->{res.setStatus(403);res.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(res.getOutputStream(),Map.of("code","FORBIDDEN","message","Bạn không có quyền thực hiện thao tác này","timestamp",Instant.now().toString(),"path",req.getRequestURI()));}))
        .addFilterBefore(jwtFilter,UsernamePasswordAuthenticationFilter.class).build();}
    @Bean CorsConfigurationSource cors(){var c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(props.getCorsAllowedOrigins().split(",")).map(String::trim).toList());c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(true);var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}
